(29479, 0, 0, 'Elder, we must speak.', 0, 1, 1, 2947902, 0, 0, 0, NULL, 0, 0),
(62838, 0, 1, 'I want to browse your goods.', 0, 3, 128, 0, 0, 0, 0, NULL, 0, 0),
(62850, 0, 0, 'Moro\'gai K\'la, your son and I have some questions for you.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0),
